<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Conway's Game of Life</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #101322;
      --panel: #191d32;
      --grid: #292e4b;
      --ink: #eef2ff;
      --muted: #929abd;
      --alive: #7cf6c5;
      --alive2: #55c9ff;
      --accent: #ff8bd8;
    }

    * { box-sizing: border-box; }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      overflow-x: hidden;
      color: var(--ink);
      background:
        radial-gradient(circle at 20% 15%, #26305c 0, transparent 30%),
        radial-gradient(circle at 85% 85%, #38234c 0, transparent 32%),
        var(--bg);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .game {
      width: min(94vw, 680px);
      padding: 26px;
      text-align: center;
      border: 1px solid #33395d;
      border-radius: 28px;
      background: color-mix(in srgb, var(--panel) 92%, transparent);
      box-shadow: 0 24px 70px #05060eaa, inset 0 1px #ffffff12;
    }

    h1 {
      margin: 0 0 5px;
      font-size: clamp(2rem, 6vw, 3.25rem);
      letter-spacing: -0.06em;
      line-height: 1;
    }

    .subtitle {
      margin: 0 0 21px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .board-wrap {
      width: min(100%, 600px);
      aspect-ratio: 1;
      margin: 0 auto 21px;
      padding: 10px;
      border-radius: 18px;
      background: #0b0d18;
      box-shadow: 0 0 0 1px #ffffff0d, 0 12px 30px #0008;
    }

    #life {
      display: block;
      width: 100%;
      height: 100%;
      min-width: 400px;
      min-height: 400px;
      max-width: 100%;
      max-height: 100%;
      border-radius: 10px;
      background: #12162a;
      cursor: crosshair;
      touch-action: none;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 11px 18px;
      color: #111425;
      background: #dfe5ff;
      font: inherit;
      font-weight: 750;
      cursor: pointer;
      transition: transform .15s, filter .15s, background .15s;
    }

    button:hover { filter: brightness(1.12); transform: translateY(-2px); }
    button:active { transform: translateY(1px) scale(.98); }
    #play { background: var(--alive); }
    #random { background: var(--alive2); }
    #clear { background: var(--accent); }

    .status {
      min-height: 1.2em;
      margin-top: 15px;
      color: var(--muted);
      font-size: .85rem;
    }

    @media (max-width: 470px) {
      body { padding: 10px; }
      .game { padding: 18px 10px; }
      .board-wrap { padding: 5px; }
      #life { min-width: 400px; min-height: 400px; transform-origin: top left; }
      .board-wrap { overflow: hidden; }
    }
  </style>
</head>
<body>
  <main class="game">
    <h1>Life, but make it ✨</h1>
    <p class="subtitle">Paint a tiny universe. Watch it figure itself out.</p>

    <div class="board-wrap">
      <canvas id="life" width="600" height="600" aria-label="Game of Life grid"></canvas>
    </div>

    <div class="controls">
      <button id="step" type="button">Step ➜</button>
      <button id="play" type="button">Play ▶</button>
      <button id="random" type="button">Randomize ✦</button>
      <button id="clear" type="button">Clear ×</button>
    </div>
    <div class="status" id="status">Generation 0 · 0 living cells</div>
  </main>

  <script>
    (() => {
      const w = 50, h = 50;
      const canvas = document.getElementById("life");
      const ctx = canvas.getContext("2d");
      const stepButton = document.getElementById("step");
      const playButton = document.getElementById("play");
      const randomButton = document.getElementById("random");
      const clearButton = document.getElementById("clear");
      const status = document.getElementById("status");

      let cells = new Uint8Array(w * h);
      let generation = 0;
      let running = false;
      let timer = null;
      let drawing = false;
      let paintValue = 1;
      let lastCell = "";

      function index(x, y) { return y * w + x; }

      function draw() {
        const dpr = window.devicePixelRatio || 1;
        const rect = canvas.getBoundingClientRect();
        const cw = rect.width, ch = rect.height;
        if (canvas.width !== Math.round(cw * dpr) || canvas.height !== Math.round(ch * dpr)) {
          canvas.width = Math.round(cw * dpr);
          canvas.height = Math.round(ch * dpr);
        }
        ctx.setTransform(dpr * cw / canvas.width, 0, 0, dpr * ch / canvas.height, 0, 0);
        ctx.fillStyle = "#12162a";
        ctx.fillRect(0, 0, cw, ch);

        const cellW = cw / w, cellH = ch / h;
        ctx.strokeStyle = "#292e4b";
        ctx.lineWidth = 0.65;
        ctx.beginPath();
        for (let x = 1; x < w; x++) {
          const px = x * cellW;
          ctx.moveTo(px, 0); ctx.lineTo(px, ch);
        }
        for (let y = 1; y < h; y++) {
          const py = y * cellH;
          ctx.moveTo(0, py); ctx.lineTo(cw, py);
        }
        ctx.stroke();

        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            if (cells[index(x, y)]) {
              const px = x * cellW, py = y * cellH;
              ctx.fillStyle = (x + y) % 5 === 0 ? "#55c9ff" : "#7cf6c5";
              ctx.fillRect(px + 1.2, py + 1.2, Math.max(1, cellW - 2.4), Math.max(1, cellH - 2.4));
            }
          }
        }

        let living = 0;
        for (const cell of cells) living += cell;
        status.textContent = `Generation ${generation} · ${living} living cells`;
      }

      function get(x, y) {
        x = Math.trunc(x); y = Math.trunc(y);
        return x < 0 || x >= w || y < 0 || y >= h ? 0 : cells[index(x, y)];
      }

      function set(x, y, value) {
        x = Math.trunc(x); y = Math.trunc(y);
        if (x < 0 || x >= w || y < 0 || y >= h) return;
        cells[index(x, y)] = value ? 1 : 0;
        draw();
      }

      function step() {
        const next = new Uint8Array(w * h);
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            let neighbours = 0;
            for (let dy = -1; dy <= 1; dy++) {
              for (let dx = -1; dx <= 1; dx++) {
                if ((dx || dy) && get(x + dx, y + dy)) neighbours++;
              }
            }
            const alive = cells[index(x, y)];
            next[index(x, y)] = alive ? (neighbours === 2 || neighbours === 3) : (neighbours === 3);
          }
        }
        cells = next;
        generation++;
        draw();
      }

      function clear() {
        cells.fill(0);
        generation = 0;
        draw();
      }

      function cellAt(event) {
        const r = canvas.getBoundingClientRect();
        return [
          Math.floor((event.clientX - r.left) / r.width * w),
          Math.floor((event.clientY - r.top) / r.height * h)
        ];
      }

      function paint(event) {
        const [x, y] = cellAt(event);
        if (x < 0 || x >= w || y < 0 || y >= h) return;
        const key = x + "," + y;
        if (key === lastCell) return;
        lastCell = key;
        set(x, y, paintValue);
      }

      canvas.addEventListener("pointerdown", event => {
        drawing = true;
        lastCell = "";
        const [x, y] = cellAt(event);
        paintValue = get(x, y) ? 0 : 1;
        canvas.setPointerCapture(event.pointerId);
        paint(event);
      });
      canvas.addEventListener("pointermove", event => { if (drawing) paint(event); });
      canvas.addEventListener("pointerup", () => { drawing = false; lastCell = ""; });
      canvas.addEventListener("pointercancel", () => { drawing = false; lastCell = ""; });

      stepButton.onclick = step;
      randomButton.onclick = () => {
        for (let i = 0; i < cells.length; i++) cells[i] = Math.random() < 0.28 ? 1 : 0;
        generation = 0;
        draw();
      };
      clearButton.onclick = clear;
      playButton.onclick = () => {
        running = !running;
        playButton.textContent = running ? "Pause ❚❚" : "Play ▶";
        if (running) {
          timer = setInterval(step, 120);
        } else {
          clearInterval(timer);
        }
      };

      window.life = { w, h, get, set, step, clear };
      window.addEventListener("resize", draw);
      draw();
    })();
  </script>
</body>
</html>
